import{_ as t,o as n,c as s,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Wido @ Ceph Day London","description":"","frontmatter":{"title":"Wido @ Ceph Day London","date":"2015-01-14T00:00:00.000Z","updated":"2015-01-14T00:00:00.000Z","tags":["Ceph","分布式存储","部署最佳实践","案例分析","高可用性"],"categories":["会议纪要","存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/Wido_@_Ceph_Day_London.md","filePath":"posts/2015/Wido_@_Ceph_Day_London.md","lastUpdated":1780459816000}'),l={name:"posts/2015/Wido_@_Ceph_Day_London.md"};function i(e,o,g,a,p,S){return n(),s("div",null,[...o[0]||(o[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>与会人员</strong>： Weo（荷兰SEF社区成员、咨询公司421的CTO）</p><p><strong>会议主题</strong>： Ceph存储系统部署经验分享与最佳实践</p><p><strong>会议内容</strong>：</p><p><strong>一、Weo个人介绍及背景</strong></p><ul><li>Weo来自荷兰，是SEF社区的早期成员，自2009年底开始参与SEF项目，拥有丰富的Ceph部署经验。</li><li>他不仅是荷兰一家托管公司的共同所有者和CTO，还拥有自己的SEF咨询公司，提供培训和咨询服务。</li><li>Weo帮助众多组织部署SEF，包括小型公司、大型企业和政府机构。</li></ul><p><strong>二、SEF部署关键点</strong></p><ol><li><strong>关注I/O性能而非存储容量</strong>： Weo强调，在设计SEF系统时，应优先考虑I/O性能，选择合适的硬盘和配置。</li><li><strong>使用SSD而非HDD</strong>： SSD具有更高的I/O性能和更低的延迟，建议使用SSD作为存储介质。</li><li><strong>优化硬件配置</strong>： 选择合适的硬件配置，例如使用多盘位系统、分配足够的内存和CPU资源。</li><li><strong>测试恢复操作</strong>： 在部署SEF系统时，应进行恢复操作测试，确保系统在硬件故障时能够正常恢复。</li><li><strong>使用专用硬件</strong>： 对于监控节点，应使用专用硬件，确保其性能稳定。</li></ol><p><strong>三、案例分析</strong></p><ul><li><strong>比利时政府项目</strong>： 该项目部署了16个节点，使用SSD进行日志记录，并使用19个1TB HDD和2.5英寸SSD作为存储介质。Weo帮助客户节省了约90万欧元。</li><li><strong>荷兰ISP项目</strong>： 该项目使用OCFS2作为共享存储，并使用SSD进行部署。Weo分享了OCFS2在RBD上的使用经验。</li></ul><p><strong>四、最佳实践</strong></p><ol><li><strong>设计系统时关注I/O性能</strong>： 选择合适的硬盘和配置，确保系统具有足够的I/O性能。</li><li><strong>使用SSD作为存储介质</strong>： SSD具有更高的I/O性能和更低的延迟。</li><li><strong>优化硬件配置</strong>： 选择合适的硬件配置，例如使用多盘位系统、分配足够的内存和CPU资源。</li><li><strong>测试恢复操作</strong>： 在部署SEF系统时，应进行恢复操作测试，确保系统在硬件故障时能够正常恢复。</li><li><strong>使用专用硬件</strong>： 对于监控节点，应使用专用硬件，确保其性能稳定。</li><li><strong>避免创建过多的放置组</strong>： 过多的放置组会消耗CPU和内存资源。</li><li><strong>不要试图超越SEF</strong>： SEF本身非常智能，应让SEF自行处理恢复操作。</li><li><strong>不要购买最昂贵的硬件</strong>： SEF设计用于硬件故障，应购买更便宜的硬件，并将节省的资金用于购买更多节点。</li></ol><p><strong>五、后续行动</strong></p><ul><li>持续关注SEF社区的动态，学习最新的SEF技术和最佳实践。</li><li>与SEF社区成员交流，分享自己的经验和心得。</li><li>在自己的项目中应用SEF的最佳实践，不断提升系统性能和可靠性。</li></ul>',15)])])}const D=t(l,[["render",i]]);export{d as __pageData,D as default};
